  .form-control, .form-select, .input-group-text { padding-top: .625rem; padding-bottom: .625rem; font-size: .875rem; }
  .form-control-sm, .form-select-sm { padding-top: .5rem; padding-bottom: .5rem; }
  .btn { --bs-btn-padding-y: .5625rem; --bs-btn-padding-x: .875rem; }
  .btn-sm { --bs-btn-padding-y: .5rem; }
  .input-group > .btn { --bs-btn-padding-y: .625rem; }
  .input-group-sm > .btn { --bs-btn-padding-y: .5rem; }
  .page-head { align-items: stretch; }
  .page-head > div:not(:first-child) { width: 100%; }
  /* one column wide, so a capped price box would just look truncated */
  .form-control[type=number], .form-control[type=date], .form-control[type=time],
  .form-control[type=month], .form-control[type=tel] { max-width: none; }
}

/* ==========================================================================
   Sales / Retail Reports — the catalogue and the report page
   ========================================================================== */
.rpt-tabs { display: inline-flex; padding: 2px; gap: 2px; border: 1px solid var(--line);
  border-radius: var(--radius-sm); background: var(--bg); }
.rpt-tab { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px;
  border-radius: 6px; font-size: .75rem; font-weight: 600; color: var(--muted); text-decoration: none; }
.rpt-tab:hover { color: var(--text); }
.rpt-tab.on { background: var(--brand); color: #fff; box-shadow: 0 1px 2px rgba(0,0,0,.06); }

.rpt-find { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
.rpt-find > .bi { color: var(--muted); }
.rpt-find .form-control { max-width: 420px; flex: 1 1 260px; }

/* Two columns that pack like the reference menu — a long group does not leave a
   hole beside a short one. */
.rpt-grid { columns: 2 440px; column-gap: 16px; }
.rpt-group { break-inside: avoid; margin-bottom: 16px; background: var(--panel);
  border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow-1);
  overflow: hidden; display: block; }
.rpt-group[hidden] { display: none; }
.rpt-head { width: 100%; display: flex; align-items: center; justify-content: space-between;
  gap: 8px; padding: 11px 16px; background: var(--panel-2); border: none;
  border-bottom: 1px solid var(--line); font-size: .75rem; font-weight: 700;
  letter-spacing: .05em; text-transform: uppercase; color: var(--text); text-align: left; }
.rpt-head:hover { background: var(--brand-100); }
.rpt-head .rpt-n { color: var(--muted); font-weight: 600; }
.rpt-head .bi { color: var(--muted); }
.rpt-group.folded .rpt-head { border-bottom: none; }
.rpt-group.folded .rpt-list { display: none; }
.rpt-list { list-style: none; margin: 0; padding: 6px; }
.rpt-list li[hidden] { display: none; }
.rpt-link { display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 8px;
  font-size: .8125rem; font-weight: 500; color: var(--text); text-decoration: none; }
.rpt-link .bi { color: var(--accent); flex: 0 0 auto; }
.rpt-link:hover { background: var(--brand-50); color: var(--brand); }
.rpt-link:hover > span:first-of-type { text-decoration: underline; text-underline-offset: 2px; }
.rpt-link.na { color: var(--muted); }
.rpt-link.na .bi { color: var(--line-strong); }
.rpt-na { margin-left: auto; font-family: var(--font-mono); font-size: .625rem; text-transform: uppercase;
  letter-spacing: .04em; color: var(--muted); background: var(--bg); border: 1px solid var(--line);
  border-radius: var(--radius-xs); padding: 1px 6px; white-space: nowrap; }

.rpt-back { display: inline-flex; align-items: center; gap: 4px; font-size: .75rem; font-weight: 600;
  color: var(--accent-hover); text-decoration: none; margin-bottom: 4px; }
.rpt-back:hover { color: var(--brand); }

.rpt-totals { display: flex; flex-wrap: wrap; gap: 10px; }
.rpt-total { display: flex; flex-direction: column; gap: 2px; min-width: 130px; padding: 10px 14px;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  box-shadow: var(--shadow-1); }
.rpt-total span { font-size: .6875rem; font-weight: 600; text-transform: uppercase; letter-spacing: .05em;
  color: var(--muted); }
.rpt-total strong { font-size: 1.125rem; font-weight: 700; color: var(--text); font-variant-numeric: tabular-nums; }

.rpt-table-card { overflow: hidden; }
.rpt-table-card .table-responsive { max-height: 70vh; }
.rpt-table thead th { position: sticky; top: 0; z-index: 1; white-space: nowrap; }
/* a register reads along its row; the card scrolls sideways rather than a date
   folding onto three lines on a phone */
.rpt-table td { white-space: nowrap; }
.rpt-table td.num { font-family: var(--font-mono); font-size: .75rem; white-space: nowrap; }
.rpt-foot { padding: 8px 14px; border-top: 1px solid var(--line); background: var(--panel-2); }
.rpt-text { white-space: pre-wrap; font-family: var(--font-mono); font-size: .75rem; background: var(--bg);
  border: 1px solid var(--line); border-radius: var(--radius-sm); padding: 12px; }
.rpt-na-icon { width: 44px; height: 44px; border-radius: 50%; background: var(--brand-100); color: var(--brand);
  display: inline-flex; align-items: center; justify-content: center; font-size: 1.25rem; flex: 0 0 auto; }

@media print {
  .brand-nav, .rpt-filters, .alert { display: none !important; }
  .rpt-table-card .table-responsive { max-height: none; overflow: visible; }
  .rpt-table thead th { position: static; }
  body { background: #fff; }
}
/* ==========================================================================
   WAREXX 2 — the Store in the same language as the warehouse
   --------------------------------------------------------------------------
   Matches frontend/src/styles.css's v2 layer: the warm page, white cards with
   16px corners and a soft shadow, sentence-case labels, pill chips (green for
   done, orange for waiting), rounded controls and the orange gradient for the
   one action a screen exists for. Inter everywhere, as in the design.
   ========================================================================== */
:root {
  --bg: #F6F5F1; --panel-2: #F7F6F2; --line: #E8E7E2; --line-strong: #D2D2D2;
  --ok: #2A8A58; --ok-bg: #EAF6EF; --ok-line: #BFE5CB; --ok-text: #2A8A58;
  --radius: 16px; --radius-lg: 16px; --radius-sm: 10px;
  --shadow-1: 0 1px 2px rgba(26,24,20,.03), 0 6px 18px -10px rgba(26,24,20,.10);
  --font-mono: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --bs-font-monospace: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --bs-body-bg: #F6F5F1; --bs-body-bg-rgb: 243,241,237;
  --bs-border-color: #E8E7E2;
  --bs-success: #35A36B; --bs-success-rgb: 22,163,74;
  --bs-success-text-emphasis: #2A8A58; --bs-success-bg-subtle: #EAF6EF; --bs-success-border-subtle: #BFE5CB;
  --bs-border-radius: 10px; --bs-border-radius-lg: 16px; --bs-border-radius-xl: 16px;
}
body { background: var(--bg); }
code, kbd, samp, pre, .font-monospace, .table td.text-end { font-variant-numeric: tabular-nums; }

/* cards */
.card { --bs-card-border-radius: 16px; --bs-card-inner-border-radius: 16px; border-radius: 16px;
  border-color: var(--line); box-shadow: var(--shadow-1); }
.card-header { font-size: 1rem; font-weight: 700; letter-spacing: -.015em; padding-top: .9rem; padding-bottom: .9rem; }
.kpi-card, .stat-card, .qa-card { border-radius: 16px; box-shadow: var(--shadow-1);
  transition: transform .14s, box-shadow .14s, border-color .14s; }
a.kpi-card:hover, .qa-card:hover { transform: translateY(-2px); border-color: #F2C9A6; background: var(--panel);
  box-shadow: 0 14px 30px -18px rgba(20,16,10,.25); }
.kpi-label, .stat-card .label { text-transform: none; letter-spacing: 0; font-size: .78rem; font-weight: 500; color: var(--text-2); }
.kpi-value, .stat-card .value { font-size: 1.6rem; font-weight: 750; letter-spacing: -.03em; color: #141414; }
.kpi-icon, .qa-ico { width: 36px; height: 36px; border-radius: 50%; background: #FCEBDD; color: #D9601B; font-size: 1rem; }
.kpi-icon.warn { background: #FCEBDD; color: #D9601B; }
.qa-title { font-size: .82rem; }
h6.text-muted { text-transform: none; letter-spacing: -.01em; font-size: .9rem; color: var(--text) !important; }
.empty-state .empty-ico { background: #FCEBDD; color: #D9601B; }

/* tables: sentence-case heads on a whisper of grey */
.table > thead > tr > th, .table > thead > tr > td { text-transform: none; letter-spacing: 0;
  font-size: .72rem; font-weight: 500; background-color: var(--panel-2); }
.table > :not(caption) > * > * { border-bottom-color: #F2EEE8; }
.table-hover > tbody > tr:hover > * { --bs-table-bg-state: #FEF6EF; }

/* chips */
.badge { text-transform: none; letter-spacing: 0; font-size: .7rem; font-weight: 600; border-radius: 8px; border: none !important; }
.badge.text-bg-success, .badge.bg-success, .status-badge.success {
  background-color: #EAF6EF !important; color: #2A8A58 !important; }
.badge.text-bg-primary, .badge.bg-primary { background-color: #FCEBDD !important; color: #C9520E !important; }
.badge.text-bg-warning, .badge.bg-warning, .status-badge.pending { background-color: #FCEBDD !important; color: #D9601B !important; }
.badge.text-bg-secondary, .badge.bg-secondary, .badge.text-bg-light, .badge.bg-light, .status-badge.neutral {
  background-color: #F1F0EC !important; color: #6B6E75 !important; }
.badge.text-bg-danger, .badge.bg-danger, .status-badge.danger { background-color: #FDEDED !important; color: #C23B3B !important; }
.badge.text-bg-info, .badge.bg-info, .status-badge.info { background-color: #EBF2FE !important; color: #2F6FD8 !important; }
.status-badge { font-family: var(--font-sans); text-transform: none; letter-spacing: 0; font-weight: 600; border-radius: 8px; border: none; }
.status-badge::before, td > .badge::before { display: none !important; }

/* buttons and controls */
.btn, .btn-sm, .btn-lg { --bs-btn-border-radius: 10px; --bs-btn-font-weight: 600; }
.btn-brand, .btn-primary { --bs-btn-bg: #D9601B; --bs-btn-border-color: #D9581A;
  --bs-btn-hover-bg: #C9520E; --bs-btn-hover-border-color: #C9520E;
  background-image: linear-gradient(180deg, #D9601B 0%, #DC5F14 100%);
  box-shadow: 0 8px 18px -10px rgba(220,95,20,.85), inset 0 1px 0 rgba(255,255,255,.2); }
.btn-brand:hover, .btn-primary:hover { background-image: linear-gradient(180deg, #E97C1F 0%, #C9520E 100%); }
.btn-success { --bs-btn-bg: #35A36B; --bs-btn-border-color: #2A8A58; --bs-btn-hover-bg: #2A8A58; --bs-btn-hover-border-color: #166534; }
.form-control, .form-select { border-radius: 10px; }
.form-control:focus, .form-select:focus { border-color: #D9601B; box-shadow: 0 0 0 3px rgba(240,122,31,.14); }
.dropdown-menu { --bs-dropdown-border-radius: 16px; box-shadow: 0 24px 60px -18px rgba(20,16,10,.28); }
.modal-content { border-radius: 16px; }

/* the standalone header is the warehouse sidebar's black */
