html.in-frame .brand-nav { background: var(--panel) !important; }
html.in-frame body { background: var(--bg); }
.kpi-value, .stat-card .value { font-size: 1.35rem; white-space: nowrap; word-break: normal; overflow: hidden; text-overflow: ellipsis; }
@media (min-width: 1400px) { .kpi-value, .stat-card .value { font-size: 1.5rem; } }

