.sx-qa-btn:hover { background: rgba(240,122,31,.10); border-color: rgba(240,122,31,.55); transform: translateY(-1px); }
.sx-qa-ico { width: 30px; height: 30px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center;
  background: rgba(240,122,31,.14); color: #D9601B; border: 1px solid rgba(240,122,31,.25); flex: 0 0 auto; }
.sx-qa-lbl { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sx-feed { padding: 8px 14px 12px; }
.sx-feed-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.sx-feed-tx b { font-size: .8rem; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sx-feed-tx small { font-size: .7rem; color: var(--muted); }
.sx-health { border-radius: 16px; padding: 20px; color: #EDE6DD; border: 1px solid #23201C;
  background: linear-gradient(165deg, #23201D 0%, #121110 100%); box-shadow: 0 20px 40px -24px rgba(0,0,0,.6); }
.sx-health header { display: flex; align-items: center; justify-content: space-between; }
.sx-health h3 { color: #fff; font-size: 1.03rem; }
.sx-health header a { color: #EDE6DD; font-size: 1.1rem; }
.sx-gauge { position: relative; width: 150px; height: 150px; margin: 14px auto 4px; }
.sx-gauge svg { width: 100%; height: 100%; }
.sx-gauge b { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
  font-size: 1.9rem; font-weight: 700; color: #fff; letter-spacing: -.02em; }
.sx-health-cap { text-align: center; font-size: .78rem; color: #CFC8BF; margin-bottom: 14px; }
.sx-legend-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 9px; }
.sx-legend-list li { display: flex; align-items: center; gap: 10px; font-size: .78rem; color: #DCD5CC; }
.sx-legend-list li b { margin-left: auto; color: #fff; font-weight: 600; }
.sx-legend-list i { width: 9px; height: 9px; border-radius: 50%; }

/* modules + foot */
.sx-mods { margin-top: 16px; }
.sx-mods .sx-head { align-items: center; padding-bottom: 4px; }
.sx-modgrid { padding: 16px 20px 20px; }
.sx-foot { display: flex; align-items: center; gap: 18px; padding: 22px 2px 10px; font-size: .72rem; color: var(--muted); }
.sx-foot b { color: var(--text); }
.sx-sp { flex: 1; }
.sx-online { display: inline-flex; align-items: center; gap: 7px; color: var(--text-2); font-weight: 500; }
.sx-online i { width: 8px; height: 8px; border-radius: 50%; background: #35A36B; box-shadow: 0 0 0 3px rgba(34,160,107,.16); }

@media (max-width: 1180px) {
  .sx { grid-template-columns: minmax(0, 1fr); }
  .sx-side { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(300px, 100%), 1fr)); align-items: start; }
}
@container (max-width: 900px) {
  .sx-hero { grid-template-columns: minmax(0, 1fr) minmax(0, 240px); } .sx-hero-tag { display: none; }
  .sx-row2, .sx-row3 { grid-template-columns: minmax(0, 1fr); }
}
@container (max-width: 760px) { .sx-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@container (max-width: 560px) { .sx-hero { grid-template-columns: minmax(0, 1fr); } .sx-hero-art { display: none; } }
@container (max-width: 420px) { .sx-kpis { grid-template-columns: minmax(0, 1fr); } }

/* the logo artwork (static/img, built by backend/tools/make_icons.py): white roof on
   the black header, the ink version on a light surface */
.brand-logo { width: 36px; height: 34px; background: url("../img/logo-mark.png") center/contain no-repeat !important; }
html.in-frame .brand-nav .brand-logo, .login-brand .brand-logo, .on-light .brand-logo {
  background-image: url("../img/logo-mark-ink.png") !important; }

/* ==========================================================================
   WAREXX 2 — one text box, the same as the warehouse app's
   36px, 10px corners, one hairline edge, firmer on hover, orange edge + soft
   ring on focus. Small (-sm) controls are 32px and large (-lg, the floor and
   delivery screens' thumb-sized ones) keep their height; both take the rest.
   ========================================================================== */
:root { --in-line: #E8E7E2; --in-line-hover: #D2D2D2; --in-focus: #D9601B; --in-ring: 0 0 0 3px rgba(240,122,31,.12); }
.form-control, .form-select {
  min-height: 36px; padding-top: 0; padding-bottom: 0; border: 1px solid var(--in-line); border-radius: 10px;
  font-size: 13px; box-shadow: none; background-color: var(--panel); transition: border-color .12s, box-shadow .12s; }
.form-control { padding-left: 12px; padding-right: 12px; }
input.form-control, .form-select { height: 36px; }
textarea.form-control { padding-top: 9px; padding-bottom: 9px; line-height: 1.5; }
.form-select { padding-left: 12px; padding-right: 32px; background-position: right 10px center; background-size: 12px; }
.form-control-sm, .form-select-sm { min-height: 32px; border-radius: 8px; font-size: 12.5px; }
input.form-control-sm, .form-select-sm { height: 32px; }
.form-control-lg, .form-select-lg { min-height: 46px; border-radius: 12px; font-size: 15px; }
input.form-control-lg, .form-select-lg { height: 46px; }
.form-control:hover:not(:disabled):not(:focus), .form-select:hover:not(:disabled):not(:focus) { border-color: var(--in-line-hover); }
.form-control:focus, .form-select:focus { border-color: var(--in-focus); box-shadow: var(--in-ring); outline: none; }
.form-control::placeholder { color: #9A9A9A; opacity: 1; }
.form-control:disabled, .form-select:disabled, .form-control[readonly] { background-color: var(--panel-2); color: var(--muted); }
.form-label { font-size: 12.5px; font-weight: 600; color: var(--text-2); margin-bottom: 6px; }
.input-group > .form-control, .input-group > .form-select { border-radius: 10px; }
.input-group > :not(:first-child):not(.dropdown-menu) { border-top-left-radius: 0; border-bottom-left-radius: 0; }
.input-group > :not(:last-child):not(.dropdown-toggle):not(.dropdown-menu) { border-top-right-radius: 0; border-bottom-right-radius: 0; }
.input-group-text { border-color: var(--in-line); background: var(--panel-2); color: var(--muted); border-radius: 10px; font-size: 13px; }
.form-check-input { border-color: var(--in-line-hover); }
.form-check-input:checked { background-color: #D9601B; border-color: #D9601B; }
.form-check-input:focus { box-shadow: var(--in-ring); border-color: var(--in-focus); }

/* ==========================================================================
   WAREXX 2 — Forms: a quiet white sheet, the same as the main app
   ========================================================================== */
form.card { padding: 24px !important; border: none; border-radius: 16px; background: #fff;
  box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 18px 40px -30px rgba(20,16,10,.35); }
form.card .row { --bs-gutter-y: 1.1rem; }
form.card > .mt-3:last-child, form.card > div:last-child:has(> .btn) { margin-top: 22px !important; padding-top: 18px;
  border-top: 1px solid #E8E7E2; display: flex; gap: 8px; }
.form-label { color: #41454E; margin-bottom: 7px; }
form.card input.form-control, form.card .form-select { height: 40px; }
.form-text { font-size: 11.5px; color: #6B6E75; margin-top: 6px; }
.modal-content { border: none; border-radius: 16px; overflow: hidden;
  box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 40px 90px -30px rgba(20,16,10,.45); }
.modal-header { background: #fff; padding: 20px 24px 16px; border-bottom: 1px solid #E8E7E2; }
.modal-title { font-size: 17px; font-weight: 700; letter-spacing: -.015em; color: #141414; }
.modal-body { padding: 20px 24px; }
.modal-footer { background: #F7F6F2; border-top: 1px solid #E8E7E2; padding: 14px 24px; gap: 8px; }
.modal-footer > * { margin: 0; }
.modal-footer .btn { height: 38px; padding: 0 18px; border-radius: 10px; font-weight: 600; }

/* ==========================================================================
   WAREXX 2 — Store registers: the same format as the warehouse list screens
   Big page title, a white card with a quiet title band, a filter tray, a calm
   table with small uppercase headers, soft status pills and quiet buttons.
   ========================================================================== */
/* page header */
.page-head { border-bottom: none; padding-bottom: 0; margin-bottom: 18px; }
.page-head h4, .page-head .page-title { font-size: 24px !important; font-weight: 750; letter-spacing: -.03em; color: #141414; }
.page-head h4 > .bi, .page-head .page-title > .bi { display: none; }
.page-head > div, .page-head .page-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.page-head .form-control-sm, .page-head .form-select-sm { height: 36px; min-height: 36px; border-radius: 10px; font-size: 13px; }
.page-head .btn-sm, .page-head .btn { height: 36px; min-height: 36px; padding: 0 14px; border-radius: 10px; font-size: 12.5px;
  display: inline-flex; align-items: center; gap: 6px; }

/* cards */
.card { border: none; border-radius: 16px; box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 1px 3px rgba(20,16,10,.04); }
.card-header { background: #fff; padding: 15px 20px; border-bottom: 1px solid #E8E7E2; font-size: 15.5px; font-weight: 700; color: #141414; }
.card-header > .bi, .card-header h5 > .bi, .card-header h6 > .bi { color: #D9601B; }
.card-footer { background: #F7F6F2; border-top: 1px solid #E8E7E2; padding: 12px 20px; }

/* a GET form above a list is a filter tray, not a document */
form.card[method="get"], form.card[method="GET"] { background: #F7F6F2; box-shadow: inset 0 0 0 1px #E8E7E2; border-radius: 16px;
  padding: 14px 18px !important; }
form.card[method="get"] > div:last-child:has(> .btn), form.card[method="GET"] > div:last-child:has(> .btn) {
  border-top: none; padding-top: 0; margin-top: 12px !important; }
form.card[method="get"] .form-label { font-size: 11.5px; color: #6B6E75; }
form.card[method="get"] input.form-control, form.card[method="get"] .form-select { height: 36px; }

/* the table */
.table { font-size: 13px; --bs-table-hover-bg: #F7F6F2; --bs-table-cell-padding-y: .8rem; --bs-table-cell-padding-x: .75rem; }
.table > thead > tr > th, .table > thead > tr > td { height: 40px; vertical-align: middle; padding-top: 0; padding-bottom: 0;
  background: #F7F6F2; color: #6B6E75; font-size: 11px; font-weight: 600; letter-spacing: .06em; white-space: nowrap;
  border-bottom: 1px solid #E8E7E2; }
.table > :not(caption) > * > * { border-bottom-color: #F1F0EC; color: #41454E; }
.card > .table > :not(caption) > tr > :first-child,
.card > .table-responsive > .table > :not(caption) > tr > :first-child { padding-left: 20px; }
.card > .table > :not(caption) > tr > :last-child,
.card > .table-responsive > .table > :not(caption) > tr > :last-child { padding-right: 20px; }
.table td.text-end { font-family: var(--font-sans); font-size: 13px; font-variant-numeric: tabular-nums; }
.table td.text-end .badge { font-family: var(--font-sans); }
.table td.small { font-size: 12.5px; color: #6B6E75; }
.table tbody a:not(.btn) { color: #141414; font-weight: 650; }
.table tbody a:not(.btn):hover { color: #D9601B; text-decoration: none; }
.table-sm { --bs-table-cell-padding-y: .55rem; }
.table-responsive { border-radius: inherit; }

/* status: a soft pill with a dot, in sentence case */
.badge, .status-badge { height: 24px; padding: 0 10px 0 9px; border-radius: 999px; font-family: var(--font-sans); font-size: 11.5px;
  font-weight: 600; letter-spacing: 0; text-transform: none; line-height: 1; gap: 6px; border: none !important; }
.badge.text-bg-success, .badge.bg-success, .status-badge.success { background-color: #EAF6EF !important; color: #2A8A58 !important; }
.badge.text-bg-warning, .badge.bg-warning, .status-badge.pending { background-color: #FDF4E3 !important; color: #A8650A !important; }
.badge.text-bg-secondary, .badge.bg-secondary, .badge.text-bg-light, .badge.bg-light, .status-badge.neutral {
  background-color: #F1F0EC !important; color: #6B6E75 !important; }
.badge.text-bg-danger, .badge.bg-danger, .status-badge.danger { background-color: #FDEDED !important; color: #C23B3B !important; }
.badge.text-bg-info, .badge.bg-info, .status-badge.info { background-color: #EBF2FE !important; color: #2F6FD8 !important; }
.badge.text-bg-primary, .badge.bg-primary { background-color: #FCEBDD !important; color: #C9520E !important; }
.badge.text-bg-dark, .badge.bg-dark { background-color: #1F1D1A !important; color: #fff !important; }
.btn .badge { height: 18px; padding: 0 6px; font-size: 11px; }
.btn .badge::before { display: none; }

/* buttons: quiet by default, one orange action per screen */
.btn-sm { min-height: 32px; border-radius: 10px; font-size: 12.5px; font-weight: 600; }
.btn-outline-secondary { --bs-btn-color: #41454E; --bs-btn-border-color: #E8E7E2; --bs-btn-bg: #fff;
  --bs-btn-hover-color: #141414; --bs-btn-hover-bg: #F1F0EC; --bs-btn-hover-border-color: #D2D2D2;
  --bs-btn-active-color: #141414; --bs-btn-active-bg: #F1F0EC; --bs-btn-active-border-color: #D2D2D2; }
.btn-outline-primary { --bs-btn-color: #C9520E; --bs-btn-border-color: #F2C9A6; --bs-btn-bg: #FCEBDD;
  --bs-btn-hover-color: #C9520E; --bs-btn-hover-bg: #FCEBDD; --bs-btn-hover-border-color: #F2C9A6;
  --bs-btn-active-color: #fff; --bs-btn-active-bg: #D9601B; --bs-btn-active-border-color: #D9601B; }
.btn-outline-danger { --bs-btn-color: #C23B3B; --bs-btn-border-color: #F2C4C4; --bs-btn-bg: #fff;
  --bs-btn-hover-color: #C23B3B; --bs-btn-hover-bg: #FDEDED; --bs-btn-hover-border-color: #F2C4C4; }
.btn-outline-success { --bs-btn-color: #2A8A58; --bs-btn-border-color: #BFE3CE; --bs-btn-bg: #fff;
  --bs-btn-hover-color: #fff; --bs-btn-hover-bg: #2A8A58; --bs-btn-hover-border-color: #2A8A58; }
.table .btn-sm { min-height: 30px; padding: 0 10px; font-size: 12px; display: inline-flex; align-items: center; gap: 5px; }

/* segmented choices and tabs */
.btn-group:has(> .btn-check) { padding: 3px; gap: 2px; background: #F1F0EC; border-radius: 12px; }
.btn-group:has(> .btn-check) > .btn { border: none !important; border-radius: 8px !important; background: transparent; color: #6B6E75; }
.btn-group:has(> .btn-check) > .btn-check:checked + .btn { background: #fff; color: #141414;
  box-shadow: 0 1px 2px rgba(20,16,10,.08), 0 0 0 1px rgba(20,16,10,.04); }
.nav-tabs { border-bottom: 1px solid #E8E7E2; gap: 4px; }
.nav-tabs .nav-link { border: none; border-bottom: 2px solid transparent; color: #6B6E75; font-weight: 600; font-size: 13px; padding: 10px 12px; }
.nav-tabs .nav-link:hover { color: #141414; border-bottom-color: #E8E7E2; }
.nav-tabs .nav-link.active { color: #141414; background: transparent; border-bottom-color: #D9601B; }

/* lists */
.list-group { --bs-list-group-border-color: #E8E7E2; border-radius: 16px; }
.list-group-item-action:hover { background: #F7F6F2; }
.table > thead > tr > th, .table > thead > tr > td { text-transform: uppercase !important; }
.table > tbody > tr > td { vertical-align: middle; }

/* ==========================================================================
   WAREXX 2 — Floor Sales: the steps as a stepper, sessions as cards
   ========================================================================== */
.fs-steps { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); margin-bottom: 22px; background: #fff; border-radius: 16px; overflow: hidden;
  box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 1px 3px rgba(20,16,10,.04); }
.fs-step { display: flex; gap: 12px; padding: 16px 18px; position: relative; }
.fs-step + .fs-step { border-left: 1px solid #E8E7E2; }
.fs-num { width: 28px; height: 28px; flex: 0 0 auto; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center;
  background: #FCEBDD; color: #D9601B; font-size: 13px; font-weight: 750; }
.fs-step b { display: block; font-size: 13.5px; font-weight: 700; color: #141414; margin-bottom: 3px; }
.fs-step span { display: block; font-size: 12px; line-height: 1.5; color: #6B6E75; }
.fs-step em { font-style: normal; font-weight: 600; color: #41454E; }

.fs-head { display: flex; align-items: center; margin-bottom: 12px; }
.fs-head h5 { margin: 0; display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 700; color: #141414; letter-spacing: -.01em; }
.fs-count { display: inline-flex; align-items: center; justify-content: center; min-width: 26px; height: 22px; padding: 0 8px; border-radius: 999px;
  background: #F1F0EC; color: #41454E; font-size: 12px; font-weight: 600; }

.fs-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 14px; }
.fs-card { display: flex; flex-direction: column; gap: 12px; padding: 16px 18px; border-radius: 16px; background: #fff; text-decoration: none !important; color: inherit;
  box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 1px 3px rgba(20,16,10,.04); border-top: 3px solid #D2D2D2; transition: box-shadow .14s, transform .14s; }
.fs-card:hover { transform: translateY(-1px); box-shadow: 0 0 0 1px #F2C9A6, 0 12px 26px -16px rgba(238,106,18,.45); }
.fs-card-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.fs-code { font-size: 18px; font-weight: 800; letter-spacing: .04em; color: #141414; }
.fs-status { display: inline-flex; align-items: center; gap: 6px; height: 24px; padding: 0 10px; border-radius: 999px; font-size: 11.5px; font-weight: 600;
  background: #F1F0EC; color: #6B6E75; white-space: nowrap; }
.fs-status::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.fs-card.st-awaiting_approval { border-top-color: #D99A1E; }
.fs-card.st-awaiting_approval .fs-status { background: #FDF4E3; color: #A8650A; }
.fs-card.st-approved { border-top-color: #35A36B; }
.fs-card.st-approved .fs-status { background: #EAF6EF; color: #2A8A58; }
.fs-card.st-rejected { border-top-color: #DC4C4C; }
.fs-card.st-rejected .fs-status { background: #FDEDED; color: #C23B3B; }
.fs-card.st-open { border-top-color: #D9601B; }
.fs-card.st-open .fs-status { background: #FCEBDD; color: #C9520E; }
.fs-cust { display: flex; align-items: center; gap: 7px; font-size: 13px; font-weight: 500; color: #41454E; }
.fs-cust .bi { color: #9A9A9A; }
.fs-figs { display: grid; grid-template-columns: 1fr 1fr; border-radius: 12px; background: #F7F6F2; box-shadow: inset 0 0 0 1px #E8E7E2; overflow: hidden; }
.fs-figs > div { display: flex; flex-direction: column; gap: 2px; padding: 10px 14px; }
.fs-figs > div + div { border-left: 1px solid #E8E7E2; }
.fs-figs span { font-size: 11px; color: #9A9A9A; }
.fs-figs b { font-size: 17px; font-weight: 750; color: #141414; letter-spacing: -.02em; }
.fs-foot { display: flex; align-items: center; justify-content: space-between; font-size: 12px; color: #9A9A9A; }
.fs-go { display: inline-flex; align-items: center; gap: 5px; font-weight: 650; color: #C9520E; }
.fs-card:hover .fs-go { color: #141414; }
.fs-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 44px 20px; text-align: center; background: #fff; border-radius: 16px;
  box-shadow: 0 0 0 1px rgba(20,16,10,.06); }
.fs-empty-ico { width: 46px; height: 46px; border-radius: 16px; display: inline-flex; align-items: center; justify-content: center; background: #FCEBDD; color: #D9601B; font-size: 20px; margin-bottom: 4px; }
.fs-empty b { font-size: 14.5px; color: #141414; }
.fs-empty span { font-size: 12.5px; color: #6B6E75; }
.fs-empty em { font-style: normal; font-weight: 600; color: #41454E; }
@media (max-width: 900px) { .fs-steps { grid-template-columns: 1fr 1fr; } .fs-step:nth-child(3) { border-left: none; } .fs-step:nth-child(n+3) { border-top: 1px solid #E8E7E2; } }
.fs-step > .fs-num { display: inline-flex; align-items: center; justify-content: center; font-size: 13px; line-height: 1; color: #D9601B; margin: 0; }
.fs-step > div > span { display: block; }

/* ==========================================================================
   WAREXX 2 — Billing Counter
   ========================================================================== */
.cx-ico { width: 34px; height: 34px; flex: 0 0 auto; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center;
  background: #FCEBDD; color: #D9601B; font-size: 16px; }
.cx-staff, .cx-place, .cx-scan, .cx-cart { border: none; border-radius: 16px; box-shadow: 0 0 0 1px rgba(20,16,10,.06), 0 1px 3px rgba(20,16,10,.04); }

/* who is serving */
.cx-staff { padding: 14px 18px !important; }
.cx-who { display: flex; align-items: center; gap: 12px; }
.cx-who h6 { font-size: 14px; font-weight: 700; color: #141414; }
.cx-staff .input-group { width: 300px !important; }
.cx-staff .input-group .form-control, .cx-staff .form-select { height: 38px; }
.cx-staff .input-group .btn { height: 38px; min-height: 38px; }
#staffChosen .badge { height: 30px; padding: 0 12px; font-size: 13px !important; }

/* the till: four chips and the next bill number */
.cx-place { padding: 12px 16px !important; background: #fff; }
.cx-place .sep { display: none !important; }
