.sc-scan-bar { display: flex; align-items: center; height: 58px; border-radius: 16px; background: #fff; box-shadow: 0 0 0 1px #E8E7E2, 0 4px 14px -10px rgba(20,16,10,.3); overflow: hidden; }
.sc-scan-bar:focus-within { box-shadow: 0 0 0 1px #F2C9A6, 0 0 0 5px rgba(240,122,31,.12); }
.sc-scan-ico { width: 58px; height: 100%; display: inline-flex; align-items: center; justify-content: center; background: #FEF6EF; color: #D9601B; font-size: 22px; flex: 0 0 auto; }
.sc-scan-bar input { flex: 1; min-width: 0; height: 100%; border: none !important; outline: none; box-shadow: none !important; padding: 0 16px; font-size: 15.5px; background: transparent; color: #141414; }
