.sc-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.sc-tile { display: flex; flex-direction: column; justify-content: center; gap: 2px; height: 54px; padding: 0 12px; margin: 0; border-radius: 12px; border: 1px solid #E8E7E2; background: #fff; cursor: pointer; transition: border-color .12s, background .12s; min-width: 0; }
.sc-tile:hover { border-color: #D2D2D2; }
.sc-tile:focus-within { border-color: #F2C9A6; box-shadow: 0 0 0 4px rgba(240,122,31,.1); }
