.sc-tile input, .sc-tile select { height: 22px !important; min-height: 0 !important; padding: 0 !important; border: none !important; box-shadow: none !important; background-color: transparent !important;
  font-size: 13.5px; font-weight: 600; color: #141414; width: 100%; max-width: none !important; }
.sc-tile select { padding-right: 18px !important; background-position: right 0 center !important; }
.sc-tile input::placeholder { color: #9A9A9A; font-weight: 500; }
.sc-wide { grid-column: span 2; }
.sc-price { grid-column: span 2; }
.sc-range { display: flex; align-items: center; gap: 8px; }
