.sc-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 40px 20px; text-align: center; background: #fff; border-radius: 16px; box-shadow: 0 0 0 1px rgba(20,16,10,.06); margin-bottom: 18px; }
.sc-empty-ico { width: 46px; height: 46px; border-radius: 16px; display: inline-flex; align-items: center; justify-content: center; background: #FDF4E3; color: #A8650A; font-size: 20px; margin-bottom: 4px; }
