.sc-tile { height: 56px; }
.sc-tile select { text-indent: -2px; padding-left: 0 !important; }
.sc-range input { height: 22px !important; padding: 0 !important; }
.sc-grid > .sc-actions { margin: 0; align-self: stretch; align-items: stretch; }
