.sc-tile.sc-price { margin-top: 0; display: flex; flex-direction: column; align-items: stretch; justify-content: center; gap: 2px; flex-wrap: nowrap; }

/* ==========================================================================
   WAREXX 2 — Store invoices
   ========================================================================== */
.iv-filters { padding: 18px 20px; }
