.rpt-head { justify-content: flex-start; gap: 12px; padding: 14px 18px; background: #fff; border: none; border-bottom: 1px solid #E8E7E2; text-transform: none; letter-spacing: 0; }
.rpt-head:hover { background: #F7F6F2; }
.rx-gico { width: 32px; height: 32px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; background: #FCEBDD; color: #D9601B; font-size: 15px; flex: 0 0 auto; }
.rx-glabel { font-size: 15px; font-weight: 700; color: #141414; letter-spacing: -.01em; }
.rpt-head .rpt-n { min-width: 24px; height: 20px; padding: 0 7px; border-radius: 999px; background: #F1F0EC; color: #6B6E75; font-size: 11.5px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; }
.rpt-head > .bi:last-child { margin-left: auto; width: 28px; height: 28px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; }
.rpt-head:hover > .bi:last-child { background: #F1F0EC; color: #141414; }
.rpt-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 8px; padding: 14px 16px 16px; }
.rpt-link { height: 100%; min-height: 48px; gap: 10px; padding: 10px 12px; border-radius: 12px; background: #F7F6F2; box-shadow: inset 0 0 0 1px #E8E7E2;
  font-size: 13px; font-weight: 500; color: #41454E; text-decoration: none !important; transition: background .12s, box-shadow .12s; }
.rpt-link > .bi:first-child { width: 28px; height: 28px; border-radius: 8px; display: inline-flex; align-items: center; justify-content: center; background: #fff; color: #D9601B;
  box-shadow: 0 0 0 1px #E8E7E2; flex: 0 0 auto; }
.rpt-link > span:first-of-type { flex: 1; min-width: 0; line-height: 1.35; }
.rpt-link:hover { background: #FEF6EF; box-shadow: inset 0 0 0 1px #F2C9A6; color: #141414; }
.rpt-link:hover > span:first-of-type { text-decoration: none; }
.rx-go { color: #D2D2D2; font-size: 12px; transition: transform .12s, color .12s; }
.rpt-link:hover .rx-go { color: #D9601B; transform: translateX(2px); }
.rpt-link.na { background: #fff; color: #9A9A9A; }
.rpt-link.na > .bi:first-child { color: #D2D2D2; }
.rpt-na { font-family: var(--font-sans); font-size: 10.5px; font-weight: 600; text-transform: none; letter-spacing: 0; padding: 2px 7px; border-radius: 999px; background: #F1F0EC; color: #9A9A9A; border: none; }

/* overview */
.rx-filters { padding: 18px 20px; }
.rx-fgrid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)) 1.3fr; gap: 10px; }
.rx-fgrid > .sc-actions { margin: 0; }
.rx-fgrid > .sc-actions .btn { height: 56px; min-height: 56px; flex: 1; justify-content: center; border-radius: 12px; }
@media (max-width: 1100px) { .rx-fgrid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }

/* Promotion cards — minimal */
.pm-grid { gap: 14px; }
.pm-card.pm-min { gap: 0; padding: 18px 20px 14px; border-radius: 16px; box-shadow: 0 0 0 1px rgba(20,16,10,.07); opacity: 1; }
.pm-card.pm-min::before { display: none; }
.pm-card.pm-min:hover { box-shadow: 0 0 0 1px rgba(20,16,10,.12), 0 8px 22px -16px rgba(20,16,10,.3); }
.pm-h { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.pm-min .pm-name { margin: 0; font-size: 15px; font-weight: 700; line-height: 1.3; }
.pm-min .pm-state { flex: 0 0 auto; height: 22px; padding: 0 9px; font-size: 11px; font-weight: 600; }
.pm-sub { margin-top: 3px; font-size: 12px; color: #9A9A9A; }
.pm-sub span { color: #41454E; font-weight: 600; }
.pm-min .pm-offer { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; margin: 12px 0 14px; padding: 0; background: none; box-shadow: none;
  font-size: 13px; line-height: 1.55; color: #41454E; font-weight: 400; min-height: 40px; }
.pm-lines { display: flex; flex-direction: column; gap: 7px; padding-top: 12px; border-top: 1px solid #F1F0EC; }
.pm-line { display: flex; align-items: center; gap: 8px; min-width: 0; font-size: 12px; color: #6B6E75; }
.pm-line .bi { color: #9A9A9A; font-size: 12px; flex: 0 0 auto; }
.pm-line span { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pm-line em { font-style: normal; font-size: 11.5px; font-weight: 600; color: #9A9A9A; }
.st-active .pm-line em { color: #2A8A58; }
.st-scheduled .pm-line em { color: #A8650A; }
.pm-min .pm-meter { height: 3px; margin: -2px 0 1px 20px; }
.pm-min .pm-foot { gap: 2px; margin-top: 14px; padding-top: 12px; }
.pm-stat { margin-right: auto; font-size: 12px; color: #9A9A9A; }
.pm-stat b { color: #141414; font-weight: 650; font-variant-numeric: tabular-nums; }
.pm-min .pm-foot .iv-ib { width: 30px; height: 30px; opacity: 0; transition: opacity .12s, background .12s; }
.pm-min:hover .pm-foot .iv-ib, .pm-min .pm-foot .iv-ib:focus { opacity: 1; }
@media (hover: none) { .pm-min .pm-foot .iv-ib { opacity: 1; } }
.pm-min.st-inactive .pm-name, .pm-min.st-expired .pm-name { color: #6B6E75 !important; }
/* Promotion cards — the essentials only */
.pm-xs { padding: 16px 18px 12px !important; }
.pm-xs .pm-offer { -webkit-line-clamp: 1; min-height: 0; margin: 8px 0 4px; font-size: 13px; color: #41454E; }
.pm-meta { font-size: 12px; color: #9A9A9A; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pm-meta em { font-style: normal; font-weight: 600; }
.st-active .pm-meta em { color: #2A8A58; }
.st-scheduled .pm-meta em { color: #A8650A; }
.pm-xs .pm-foot { margin-top: 12px; padding-top: 10px; }

/* Store banner: the photograph in the right-hand panel */
.sx-hero-art img { object-position: 62% 55%; }
.sx-hero-art::after { content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(248,226,203,.35) 0%, rgba(248,226,203,0) 40%), linear-gradient(180deg, rgba(255,240,225,.08), rgba(60,30,10,.12)); }
.sx-hero-art .sx-ribbon { z-index: 1; }
/* Promotion cards — a touch of colour */
.pm-xs { padding-left: 21px !important; transition: transform .16s ease, box-shadow .16s ease; }
.pm-xs::before { display: block !important; left: 0; top: 14px; bottom: 14px; right: auto; width: 3px; height: auto; border-radius: 0 6px 6px 0; background: #E8E7E2; }
.pm-xs.st-active::before { background: linear-gradient(180deg, #35A36B, #35A36B); }
.pm-xs.st-scheduled::before { background: linear-gradient(180deg, #D99A1E, #D99A1E); }
.pm-xs.st-inactive::before { background: #F2C4C4; }
.pm-xs:hover { transform: translateY(-2px); box-shadow: 0 0 0 1px rgba(20,16,10,.08), 0 14px 28px -18px rgba(20,16,10,.35) !important; }
.pm-xs .pm-h { align-items: center; }
.pm-ico { width: 30px; height: 30px; flex: 0 0 auto; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; font-size: 14px;
  background: #F1F0EC; color: #9A9A9A; margin-right: 2px; }
.st-active .pm-ico { background: linear-gradient(135deg, #FCEBDD, #FCEBDD); color: #D9601B; }
.st-scheduled .pm-ico { background: #FDF4E3; color: #D99A1E; }
.st-inactive .pm-ico { background: #FDEDED; color: #DC4C4C; }
.pm-xs .pm-name { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pm-xs .pm-offer, .pm-xs .pm-meta { padding-left: 40px; }
.pm-given { color: #C9520E !important; }
.st-expired .pm-given, .st-inactive .pm-given { color: #6B6E75 !important; }
.sx-promo-art { right: 0 !important; width: 64% !important; object-position: 60% 50%; opacity: 1 !important;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, rgba(0,0,0,.55) 28%, #000 58%) !important; mask-image: linear-gradient(90deg, transparent 0%, rgba(0,0,0,.55) 28%, #000 58%) !important; }
.sx-promo-art { width: 52% !important; object-position: 66% 50%;
  -webkit-mask-image: linear-gradient(90deg, transparent 0%, rgba(0,0,0,.35) 35%, #000 75%) !important; mask-image: linear-gradient(90deg, transparent 0%, rgba(0,0,0,.35) 35%, #000 75%) !important; }
.sx-promo-tx { max-width: 72% !important; }
.sx-promo-tx { max-width: 64% !important; } .sx-promo-art { width: 48% !important; }


/* ==========================================================================
   WAREXX DESIGN SYSTEM — Store
   The same tokens as frontend/src/design-system.css, mapped onto the Bootstrap
   classes the Store templates use. Kept last so it is the final word.
   ========================================================================== */
:root {
  --wx-black: #141414; --wx-brand: #D9601B; --wx-brand-dark: #C9520E;
  --wx-bg: #F6F5F1; --wx-ivory: #F7F6F2; --wx-surface-2: #F1F0EC;
  --wx-line: #E8E7E2; --wx-line-strong: #D2D2D2;
  --wx-gray: #9A9A9A; --wx-muted: #6B6E75; --wx-dark: #41454E;
  --wx-tint: #FCEBDD; --wx-wash: #FEF6EF; --wx-tint-line: #F2C9A6;
  --wx-ok: #35A36B; --wx-ok-text: #2A8A58; --wx-ok-bg: #EAF6EF;
  --wx-info: #3B82F6; --wx-info-text: #2F6FD8; --wx-info-bg: #EBF2FE;
  --wx-warn: #D99A1E; --wx-warn-text: #A8650A; --wx-warn-bg: #FDF4E3;
  --wx-err: #DC4C4C; --wx-err-text: #C23B3B; --wx-err-bg: #FDEDED;
  --wx-r-sm: 6px; --wx-r: 10px; --wx-r-md: 12px; --wx-r-lg: 16px;
  --wx-h-sm: 30px; --wx-h: 36px;
  --wx-card: 0 0 0 1px rgba(20,20,20,.06), 0 1px 2px rgba(20,20,20,.04);
  --wx-pop: 0 16px 40px -18px rgba(20,20,20,.35), 0 0 0 1px rgba(20,20,20,.06);
  --wx-ring: 0 0 0 3px rgba(217,96,27,.16);
  --brand: var(--wx-brand); --accent: var(--wx-brand-dark); --brand-dark: var(--wx-brand-dark);
  --bg: var(--wx-bg); --panel-2: var(--wx-ivory); --line: var(--wx-line); --muted: var(--wx-muted); --text: var(--wx-black);
  --in-focus: var(--wx-brand); --in-ring: var(--wx-ring); --in-line: var(--wx-line-strong);
}
body { background: var(--wx-bg) !important; color: var(--wx-black); }

/* buttons */
.btn { height: var(--wx-h); min-height: var(--wx-h); padding: 0 14px; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  border-radius: var(--wx-r) !important; font-size: 13px; font-weight: 600; line-height: 1; box-shadow: none !important; }
.btn-sm { height: var(--wx-h-sm); min-height: var(--wx-h-sm); padding: 0 10px; font-size: 12px; border-radius: var(--wx-r-sm) !important; }
.btn-lg { height: 44px; min-height: 44px; }
.btn-brand { --bs-btn-bg: var(--wx-brand); --bs-btn-border-color: var(--wx-brand); --bs-btn-color: #fff;
  --bs-btn-hover-bg: var(--wx-brand-dark); --bs-btn-hover-border-color: var(--wx-brand-dark); --bs-btn-hover-color: #fff;
  background-image: none !important; background-color: var(--wx-brand) !important; border-color: var(--wx-brand) !important; color: #fff !important; }
.btn-brand:hover { background-color: var(--wx-brand-dark) !important; border-color: var(--wx-brand-dark) !important; }
.btn-outline-secondary, .btn-light { --bs-btn-bg: #fff; --bs-btn-color: var(--wx-black); --bs-btn-border-color: var(--wx-line-strong);
  --bs-btn-hover-bg: var(--wx-ivory); --bs-btn-hover-color: var(--wx-black); --bs-btn-hover-border-color: #BDBDBD; }
.btn-outline-primary { --bs-btn-bg: var(--wx-wash); --bs-btn-color: var(--wx-brand-dark); --bs-btn-border-color: var(--wx-tint-line);
  --bs-btn-hover-bg: var(--wx-tint); --bs-btn-hover-color: var(--wx-brand-dark); --bs-btn-hover-border-color: var(--wx-tint-line); }
.btn-outline-danger { --bs-btn-bg: #fff; --bs-btn-color: var(--wx-err-text); --bs-btn-border-color: #F2C4C4;
  --bs-btn-hover-bg: var(--wx-err-bg); --bs-btn-hover-color: var(--wx-err-text); --bs-btn-hover-border-color: #F2C4C4; }
.btn-outline-success { --bs-btn-bg: #fff; --bs-btn-color: var(--wx-ok-text); --bs-btn-border-color: #BFE3CE;
  --bs-btn-hover-bg: var(--wx-ok-bg); --bs-btn-hover-color: var(--wx-ok-text); --bs-btn-hover-border-color: #BFE3CE; }
.btn:focus-visible { box-shadow: var(--wx-ring) !important; }

/* inputs */
.form-control, .form-select { border-color: var(--wx-line-strong); border-radius: var(--wx-r) !important; font-size: 13px; color: var(--wx-black); }
input.form-control, .form-select { height: var(--wx-h); }
.form-control:focus, .form-select:focus { border-color: var(--wx-brand) !important; box-shadow: var(--wx-ring) !important; }
.form-control::placeholder { color: var(--wx-gray) !important; }
.form-label { font-size: 12px; font-weight: 600; color: var(--wx-dark); }
.form-text { font-size: 11px; color: var(--wx-muted); }
.form-check-input:checked { background-color: var(--wx-brand); border-color: var(--wx-brand); }

/* cards */
.card { border: none !important; border-radius: var(--wx-r-lg) !important; box-shadow: var(--wx-card) !important; }
.card-header { background: #fff; border-bottom: 1px solid var(--wx-line); font-size: 15.5px; font-weight: 700; color: var(--wx-black); }

/* tables */
.table > thead > tr > th { background: var(--wx-ivory) !important; color: var(--wx-muted) !important; font-size: 11px; font-weight: 600; letter-spacing: .06em; }
.table { --bs-table-hover-bg: var(--wx-wash); font-size: 13px; }
.table > :not(caption) > * > * { border-bottom-color: var(--wx-surface-2); }

/* status badges: the same meaning-to-colour map as the warehouse app */
.badge { height: 22px; padding: 0 9px 0 8px; border-radius: 999px !important; font-size: 11px; font-weight: 600; text-transform: none; letter-spacing: 0; border: none !important; }
.badge.text-bg-success, .badge.bg-success, .status-badge.success { background-color: var(--wx-ok-bg) !important; color: var(--wx-ok-text) !important; }
.badge.text-bg-warning, .badge.bg-warning, .status-badge.pending { background-color: var(--wx-warn-bg) !important; color: var(--wx-warn-text) !important; }
.badge.text-bg-info, .badge.bg-info, .status-badge.info { background-color: var(--wx-info-bg) !important; color: var(--wx-info-text) !important; }
.badge.text-bg-danger, .badge.bg-danger, .status-badge.danger { background-color: var(--wx-err-bg) !important; color: var(--wx-err-text) !important; }
.badge.text-bg-secondary, .badge.bg-secondary, .badge.text-bg-light, .badge.bg-light, .status-badge.neutral { background-color: var(--wx-surface-2) !important; color: var(--wx-muted) !important; }
.badge.text-bg-primary, .badge.bg-primary { background-color: var(--wx-tint) !important; color: var(--wx-brand-dark) !important; }
.badge.text-bg-dark, .badge.bg-dark { background-color: var(--wx-black) !important; color: #fff !important; }

/* notices */
.alert { border: none; border-radius: var(--wx-r-md); font-size: 13px; }
.alert-warning { background: var(--wx-warn-bg); color: var(--wx-dark); box-shadow: inset 0 0 0 1px #F1D9A6; }
.alert-info { background: var(--wx-info-bg); color: var(--wx-dark); box-shadow: inset 0 0 0 1px #C9DBFB; }
.alert-danger { background: var(--wx-err-bg); color: var(--wx-dark); box-shadow: inset 0 0 0 1px #F2C4C4; }
.alert-success { background: var(--wx-ok-bg); color: var(--wx-dark); box-shadow: inset 0 0 0 1px #BFE3CE; }
.alert-secondary { background: var(--wx-ivory); color: var(--wx-dark); box-shadow: inset 0 0 0 1px var(--wx-line); }

/* modals */
.modal-content { border: none; border-radius: var(--wx-r-lg) !important; box-shadow: var(--wx-pop) !important; }
.modal-backdrop.show { opacity: .36; }

/* tabs */
.nav-tabs .nav-link.active { border-bottom-color: var(--wx-brand); }

/* flat accents: cards do not float, chrome has no gradients */
.fs-card:hover, .pm-xs:hover, .sx-kpi:hover, .qa-card:hover { transform: none !important; }
.pm-xs.st-active::before { background: var(--wx-ok) !important; }
.pm-xs.st-scheduled::before { background: var(--wx-warn) !important; }
.st-active .pm-ico { background: var(--wx-tint) !important; }
.inv-cat, .pm-stack, .iv-pay.pay-upi { background: var(--wx-surface-2) !important; color: var(--wx-dark) !important; }
.sc-scan { background: #fff !important; }

@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .001s !important; transition-duration: .001s !important; } }
@media (max-width: 640px) { .btn { height: 40px; min-height: 40px; } }
